 // --- Tool definitions ---

 [Description("A notebook for collecting and organizing research findings.")]
 public sealed class ResearchNotes
 {
     private readonly List<NoteEntry> _notes = [];

     [Description("Save a research note with a topic tag and content.")]
     public string AddNote(
         [Description("Short topic tag for the note")] string topic,
         [Description("The note content to save")] string content)
     {
         _notes.Add(new NoteEntry(topic, content, DateTime.UtcNow));
         return $"Note #{_notes.Count} saved under '{topic}'.";
     }

     [Description("List all saved notes, optionally filtered by topic.")]
     public string ListNotes(
         [Description("Optional topic filter (leave empty for all)")] string? topic = null)
     {
         var filtered = string.IsNullOrWhiteSpace(topic)
             ? _notes
             : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

         if (filtered.Count == 0)
             return "No notes found.";

         return string.Join("\n\n", filtered.Select((n, i) =>
             $"[{i + 1}] ({n.Topic}) {n.Content}"));
     }

     public IReadOnlyList<NoteEntry> GetAllNotes() => _notes.AsReadOnly();

     public sealed record NoteEntry(string Topic, string Content, DateTime Timestamp);
 }

 [Description("Web search capabilities for research.")]
 public static class WebSearchTool
 {
     private static readonly HttpClient Http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "application/json" },
         },
         Timeout = TimeSpan.FromSeconds(15),
     };

     [Description("Search the web for information on a query. Returns relevant results as text.")]
     public static async Task<string> SearchWebAsync(
         [Description("The search query string")] string query,
         [Description("Max number of results to return (1-5)")] int maxResults = 3)
     {
         maxResults = Math.Clamp(maxResults, 1, 5);

         try
         {
             // Use Wikipedia API as a free, reliable search source
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}" +
                       $"&srlimit={maxResults}&format=json&utf8=1";

             var json = await Http.GetStringAsync(url);
             using var doc = JsonDocument.Parse(json);
             var results = doc.RootElement.GetProperty("query").GetProperty("search");

             if (results.GetArrayLength() == 0)
                 return $"No results found for '{query}'.";

             var entries = new List<string>();
             foreach (var item in results.EnumerateArray())
             {
                 var title = item.GetProperty("title").GetString();
                 var snippet = StripHtml(item.GetProperty("snippet").GetString() ?? "");
                 entries.Add($"• {title}: {snippet}");
             }

             return $"Search results for '{query}':\n" + string.Join("\n", entries);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     [Description("Fetch the summary of a specific Wikipedia article by title.")]
     public static async Task<string> GetArticleSummaryAsync(
         [Description("The exact title of the Wikipedia article")] string title)
     {
         try
         {
             var encoded = Uri.EscapeDataString(title);
             var url = $"https://en.wikipedia.org/api/rest_v1/page/summary/{encoded}";
             var json = await Http.GetStringAsync(url);
             using var doc = JsonDocument.Parse(json);
             var extract = doc.RootElement.GetProperty("extract").GetString();
             return string.IsNullOrWhiteSpace(extract)
                 ? $"No summary available for '{title}'."
                 : $"Article: {title}\n{extract}";
         }
         catch (Exception ex)
         {
             return $"Failed to fetch article '{title}': {ex.Message}";
         }
     }

     private static string StripHtml(string html) =>
         System.Text.RegularExpressions.Regex.Replace(html, "<.*?>", "");
 }

 // --- Agent runner ---

 public sealed class ResearchRunner(IChatClient chatClient, ResearchNotes notes)
 {
     public async Task RunAsync(string[] args)
     {
         var topic = args.Length > 0
             ? string.Join(' ', args)
             : PromptForTopic();

         Console.WriteLine($"\n🔍 Researching: {topic}\n");

         var systemPrompt = """
             You are a research agent. Your job is to thoroughly research a given topic.

             Follow this workflow:
             1. Search the web for information on the topic (use multiple searches with different queries).
             2. Read article summaries for the most relevant results.
             3. Take notes on key findings using the note-taking tool — organize by sub-topics.
             4. After gathering enough information, list all your notes and write a comprehensive summary.

             Be thorough but concise. Aim for 3-5 searches and at least 5 notes before summarizing.
             Always end by presenting a structured summary of your research findings to the user.
             """;

         var chatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 4096,
             Tools =
             [
                 AIFunctionFactory.Create((string query, int maxResults) =>
                     WebSearchTool.SearchWebAsync(query, maxResults)),
                 AIFunctionFactory.Create((string title) =>
                     WebSearchTool.GetArticleSummaryAsync(title)),
                 AIFunctionFactory.Create((string topic, string content) =>
                     notes.AddNote(topic, content)),
                 AIFunctionFactory.Create((string? topic) =>
                     notes.ListNotes(topic)),
             ],
         };

         var messages = new List<ChatMessage>
         {
             new(ChatRole.System, systemPrompt),
             new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
         };

         Console.WriteLine("Agent is working...\n");

         await foreach (var update in chatClient.GetStreamingResponseAsync(messages, chatOptions))
         {
             if (!string.IsNullOrEmpty(update.Text))
                 Console.Write(update.Text);
         }

         Console.WriteLine("\n\n--- Research Notes Collected ---");
         foreach (var note in notes.GetAllNotes())
         {
             Console.WriteLine($"  [{note.Topic}] {note.Content[..Math.Min(note.Content.Length, 120)]}");
         }
         Console.WriteLine($"\nTotal notes: {notes.GetAllNotes().Count}");
     }

     private static string PromptForTopic()
     {
         Console.Write("Enter a research topic: ");
         var topic = Console.ReadLine()?.Trim();
         return string.IsNullOrWhiteSpace(topic)
             ? "the history and impact of artificial intelligence"
             : topic;
     }
 }
